INSERT INTO program_narratives (program_id, kind, title, detail, sort_order) VALUES
  ('PRG-01', 'CAPAIAN', 'Pemindahan Makam Tionghoa', 'Telah selesai pengambilan dan pemindahan makam sebanyak 170 makam dengan capaian 100% sesuai surat keterangan pemindahan dari YPKOT.', 0),
  ('PRG-01', 'CAPAIAN', 'Relokasi Aset Pemerintah Desa Sungai Duri II dan Sungai Limau', 'Telah disampaikan laporan progres pekerjaan dan pemutusan kontrak pekerjaan relokasi aset; saat ini dalam proses penunjukan vendor pengganti.', 1),
  ('PRG-01', 'CAPAIAN', 'Pensertipikatan HGB di atas HPL Konsesi', 'Telah dilakukan pembayaran PNBP pengukuran bidang tanah yang akan dimohonkan HGB Konsesi Terminal Kijing.', 2),
  ('PRG-01', 'CAPAIAN', 'Pendaftaran Pensertipikatan RJN', 'Telah dilakukan penyerahan hasil pengadaan tanah RJN dengan prestasi fisik 100%.', 3),
  ('PRG-01', 'ISU', 'Kelengkapan Dokumen Pertanahan', 'Dokumen pensertipikatan HGB Konsesi dan RJN masih dalam proses pemenuhan dan verifikasi serta penunjukan Notaris/PPAT.', 0),
  ('PRG-01', 'ISU', 'Penyelesaian Relokasi Aset', 'Relokasi dan pengosongan lahan masih memerlukan koordinasi dengan stakeholder dan penunjukan kembali vendor baru.', 1),
  ('PRG-01', 'NEXT_STEP', 'Sertipikasi Ex. Lahan Makam Tionghoa', 'Penyiapan dokumen terkait hasil pengadaan tanah.', 0),
  ('PRG-01', 'NEXT_STEP', 'Relokasi Aset Pemerintah Desa Sungai Duri II dan Sungai Limau', 'Monitoring dan evaluasi proses pekerjaan (vendor pengganti).', 1),
  ('PRG-01', 'NEXT_STEP', 'Pensertipikatan HGB di atas HPL Konsesi', 'Penetapan Notaris/PPAT untuk proses pensertipikatan HGB Konsesi Terminal Kijing dan melengkapi kekurangan dokumen.', 2),
  ('PRG-01', 'NEXT_STEP', 'Pendaftaran Pensertipikatan RJN', 'Inventarisasi kelengkapan dokumen persyaratan permohonan pensertipikatan hasil pengadaan tanah RJN.', 3),
  ('PRG-02', 'CAPAIAN', 'Relokasi Aset TNI AL', 'Telah dilakukan kontrak dengan Notaris/PPAT untuk pembayaran dan sertipikasi tanah pengganti BMN TNI AL serta pendampingan Kejagung dalam proses tukar menukar BMN TNI AL.', 0),
  ('PRG-02', 'CAPAIAN', 'Relokasi Aset PT KBN', 'Telah dilakukan Serah Sedia Lahan untuk pembangunan jalan pengganti dan proses pekerjaan bangunan pengganti.', 1),
  ('PRG-02', 'CAPAIAN', 'Pendaftaran Pensertipikatan Hasil Pengadaan Tanah NPEA', 'Telah dilakukan penyerahan hasil pengadaan tanah (parsial) dan dalam proses permohonan pemecahan bidang tanah.', 2),
  ('PRG-02', 'CAPAIAN', 'Konsinyasi dan Eksekusi Pengosongan Tanah', 'Dari 27 danom yang dikonsinyasi, telah keluar 24 penetapan PN Jakarta Utara dan 3 danom dalam proses sidang penetapan.', 3),
  ('PRG-02', 'ISU', 'Relokasi Aset & Penyelesaian Lahan', 'Relokasi TNI AL/KBN dan pengosongan tanah masih bergantung pada koordinasi stakeholder serta penyelesaian aset pengganti.', 0),
  ('PRG-02', 'ISU', 'Pensertipikatan Tanah NPEA', 'Proses pemecahan bidang dan sertipikasi masih memerlukan kelengkapan dokumen serta koordinasi dengan BPN.', 1),
  ('PRG-02', 'NEXT_STEP', 'Relokasi Aset TNI AL', 'Koordinasi intensif dengan stakeholder terkait (TNI AL, Kemhan, Kemenkeu, BPN dan Kejagung).', 0),
  ('PRG-02', 'NEXT_STEP', 'Relokasi Aset PT KBN', 'Monitoring dan evaluasi proses pembangunan bangunan pengganti.', 1),
  ('PRG-02', 'NEXT_STEP', 'Pendaftaran Pensertipikatan Hasil Pengadaan Tanah NPEA', 'Percepatan pemecahan bidang tanah dan penyiapan kelengkapan dokumen permohonan sertipikasi.', 2),
  ('PRG-02', 'NEXT_STEP', 'Konsinyasi dan Eksekusi Pengosongan Tanah', 'Monitoring dan koordinasi progres atas sisa 3 danom yang belum keluar penetapan pengadilan.', 3),
  ('PRG-03', 'CAPAIAN', 'Sorong', 'Telah dilakukan pembahasan monitoring progres pengadaan tanah Sorong dengan Regional 4 dan Cabang Sorong.', 0),
  ('PRG-03', 'CAPAIAN', 'Batang', 'Telah dilakukan pembahasan persiapan penunjukan Notaris terkait proses pensertipikatan HPL.', 1),
  ('PRG-03', 'CAPAIAN', 'Kuala Tanjung', 'Telah dilakukan pembahasan monitoring progres pengadaan tanah Kuala Tanjung dengan Regional 1.', 2),
  ('PRG-03', 'ISU', 'Pensertipikatan Lahan', 'Proses sertipikasi lahan Sorong dan HPL Batang masih memerlukan koordinasi dengan BPN serta penyelesaian administrasi terkait.', 0),
  ('PRG-03', 'ISU', 'Pengadaan Tanah Kuala Tanjung', 'Penyelesaian pengadaan tanah masih menunggu tindak lanjut proses di Kementerian ATR/BPN.', 1),
  ('PRG-03', 'NEXT_STEP', 'Sorong', 'Monitoring dan koordinasi tindak lanjut dengan Regional 4 dan Cabang Sorong terkait pensertipikatan lahan reklamasi 5 Ha. SKK sudah diberikan kepada ED Regional 4.', 0),
  ('PRG-03', 'NEXT_STEP', 'Batang', 'Monitoring dan evaluasi hasil pekerjaan Notaris.', 1),
  ('PRG-03', 'NEXT_STEP', 'Kuala Tanjung', 'Monitoring dan asistensi bersama Regional 1 dan PPK; surat ke direksi PPK untuk percepatan dengan Kanwil BPN setempat dan tindak lanjut tim kantor pusat ke Kementerian ATR/BPN.', 2);
